-- Run only after the production taxonomy has reached this database and 0263 is installed.
-- Existing singleton Feature values remain unchanged; widening is backward compatible.
CREATE TABLE _hkgs_many_guard(ok INTEGER NOT NULL CHECK(ok=1));
INSERT INTO _hkgs_many_guard SELECT (SELECT count(*) FROM property WHERE id='af38c4209f82' AND projectId='YuSFnia9VOtG' AND key='stratigraphy' AND type='classifier' AND component='SelectField' AND dataType='text' AND cardinality IN ('one','many'))=1
 AND (SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name IN ('feature_property_multi_select_insert','feature_property_multi_select_update'))=2;
CREATE VIEW _hkgs_many_snapshot AS SELECT (SELECT json_group_object(id,json(content)) FROM (
 SELECT property.id AS id,json_object('record',json(json_object('organisationId',"property"."organisationId",'hubId',"property"."hubId",'projectId',"property"."projectId",'scope',"property"."scope",'type',"property"."type",'key',"property"."key",'dataType',"property"."dataType",'dateResolution',"property"."dateResolution",'timeMaxHour',"property"."timeMaxHour",'cardinality',"property"."cardinality",'presentation',"property"."presentation",'audience',"property"."audience",'component',"property"."component",'min',"property"."min",'max',"property"."max",'isTranslatable',json(CASE WHEN "property"."isTranslatable" IS NULL THEN 'null' WHEN "property"."isTranslatable" THEN 'true' ELSE 'false' END),'isUserContributable',json(CASE WHEN "property"."isUserContributable" IS NULL THEN 'null' WHEN "property"."isUserContributable" THEN 'true' ELSE 'false' END),'isDefaultEnabled',json(CASE WHEN "property"."isDefaultEnabled" IS NULL THEN 'null' WHEN "property"."isDefaultEnabled" THEN 'true' ELSE 'false' END))),
 'i18n',json((SELECT json_group_object(locale,json(content)) FROM (SELECT propertyI18n.locale AS locale,json_patch(json_object('label',"propertyI18n"."label",'labelGen',json(CASE WHEN "propertyI18n"."labelGen" IS NULL THEN 'null' WHEN "propertyI18n"."labelGen" THEN 'true' ELSE 'false' END),'placeholder',"propertyI18n"."placeholder",'placeholderGen',json(CASE WHEN "propertyI18n"."placeholderGen" IS NULL THEN 'null' WHEN "propertyI18n"."placeholderGen" THEN 'true' ELSE 'false' END)),CASE WHEN "propertyI18n"."translationProvenance" IS NULL THEN '{}' ELSE json_object('translationProvenance',json("propertyI18n"."translationProvenance")) END) AS content FROM propertyI18n WHERE propertyI18n.propertyId=property.id AND COALESCE(propertyI18n.isAutomaticOnly,0)=0 ORDER BY propertyI18n.locale))),
 'values',json((SELECT json_group_object(id,json(content)) FROM (SELECT propertyValue.id AS id,json_object('record',json(json_object('rank',"propertyValue"."rank",'value',"propertyValue"."value")),'i18n',json((SELECT json_group_object(locale,json(content)) FROM (SELECT propertyValueI18n.locale AS locale,json_patch(json_object('value',"propertyValueI18n"."value",'valueGen',json(CASE WHEN "propertyValueI18n"."valueGen" IS NULL THEN 'null' WHEN "propertyValueI18n"."valueGen" THEN 'true' ELSE 'false' END)),CASE WHEN "propertyValueI18n"."translationProvenance" IS NULL THEN '{}' ELSE json_object('translationProvenance',json("propertyValueI18n"."translationProvenance")) END) AS content FROM propertyValueI18n WHERE propertyValueI18n.propertyValueId=propertyValue.id AND COALESCE(propertyValueI18n.isAutomaticOnly,0)=0 ORDER BY propertyValueI18n.locale)))) AS content FROM propertyValue WHERE propertyValue.propertyId=property.id ORDER BY propertyValue.id)))
 ) AS content FROM property WHERE scope='project' AND projectId='YuSFnia9VOtG' ORDER BY property.id)) AS content;
CREATE TABLE _hkgs_many_pending AS SELECT id FROM property WHERE id='af38c4209f82' AND cardinality='one';
-- Fail closed if the live catalogue differs from its authoritative history head.
INSERT INTO _hkgs_many_guard SELECT NOT EXISTS(SELECT 1 FROM propertyCatalogRevisionHead h JOIN propertyCatalogRevision r ON r.id=h.currentRevisionId WHERE h.scope='project' AND h.resourceId='YuSFnia9VOtG' AND r.content<>(SELECT content FROM _hkgs_many_snapshot));
INSERT INTO propertyCatalogRevisionWrite(scope,resourceId,token) SELECT 'project','YuSFnia9VOtG','hkgs-stratigraphy-many-v1' WHERE EXISTS(SELECT 1 FROM _hkgs_many_pending);
INSERT INTO revisionChangeSet(id,actorId,origin,reason,createdAt) SELECT 'hkgs-stratigraphy-many-v1-baseline','system:migration:hkgs-stratigraphy-many-v1','migration','Ghost Signs catalogue before widening Stratigraphy',strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE EXISTS(SELECT 1 FROM _hkgs_many_pending) AND NOT EXISTS(SELECT 1 FROM propertyCatalogRevisionHead WHERE scope='project' AND resourceId='YuSFnia9VOtG');
INSERT INTO propertyCatalogRevision(id,scope,resourceId,previousRevisionId,changeSetId,content) SELECT 'hkgs-stratigraphy-many-v1-baseline','project','YuSFnia9VOtG',NULL,'hkgs-stratigraphy-many-v1-baseline',(SELECT content FROM _hkgs_many_snapshot) WHERE EXISTS(SELECT 1 FROM _hkgs_many_pending) AND NOT EXISTS(SELECT 1 FROM propertyCatalogRevisionHead WHERE scope='project' AND resourceId='YuSFnia9VOtG');
INSERT INTO propertyCatalogRevisionHead(scope,resourceId,currentRevisionId,generation) SELECT 'project','YuSFnia9VOtG','hkgs-stratigraphy-many-v1-baseline',0 WHERE EXISTS(SELECT 1 FROM _hkgs_many_pending) AND NOT EXISTS(SELECT 1 FROM propertyCatalogRevisionHead WHERE scope='project' AND resourceId='YuSFnia9VOtG');
UPDATE property SET cardinality='many',modifiedAt=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id IN (SELECT id FROM _hkgs_many_pending);
INSERT INTO revisionChangeSet(id,actorId,origin,reason,createdAt) SELECT 'hkgs-stratigraphy-many-v1','system:migration:hkgs-stratigraphy-many-v1','migration','Allow multiple Stratigraphy selections without changing existing assignments',strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE EXISTS(SELECT 1 FROM _hkgs_many_pending);
INSERT INTO propertyCatalogRevision(id,scope,resourceId,previousRevisionId,changeSetId,content) SELECT 'hkgs-stratigraphy-many-v1','project',h.resourceId,h.currentRevisionId,'hkgs-stratigraphy-many-v1',(SELECT content FROM _hkgs_many_snapshot) FROM propertyCatalogRevisionHead h WHERE h.scope='project' AND h.resourceId='YuSFnia9VOtG' AND EXISTS(SELECT 1 FROM _hkgs_many_pending);
UPDATE propertyCatalogRevisionHead SET currentRevisionId='hkgs-stratigraphy-many-v1',generation=generation+1 WHERE scope='project' AND resourceId='YuSFnia9VOtG' AND EXISTS(SELECT 1 FROM _hkgs_many_pending);
DELETE FROM propertyCatalogRevisionWrite WHERE scope='project' AND resourceId='YuSFnia9VOtG' AND token='hkgs-stratigraphy-many-v1';
DROP TABLE _hkgs_many_pending;
DROP VIEW _hkgs_many_snapshot;
DROP TABLE _hkgs_many_guard;
